def union_find_ops(n, ops):
    parent = list(range(n))
    size = [1] * n
    sets = n
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    out = []
    for op in ops:
        if op[0] == 'union':
            a, b = find(op[1]), find(op[2])
            if a != b:
                if size[a] < size[b]:
                    a, b = b, a
                parent[b] = a
                size[a] += size[b]
                sets -= 1
        elif op[0] == 'connected':
            out.append(find(op[1]) == find(op[2]))
        else:
            out.append(sets)
    return out
